# Fix logo references in all HTML files\n# Replace any src attribute containing 'logo' with the canonical logo path and add CSS class\n# Also inject a link to the shared logo CSS before </head>\n\nGet-ChildItem -Path (Get-Location) -Recurse -Filter *.html | ForEach-Object {\n    $file = $_.FullName\n    $content = Get-Content -Path $file -Raw\n    # Replace src="...logo..." with the standardized path and class\n    $content = $content -replace 'src="[^"]*logo[^"]*"', 'src="/assets/logo.svg" class="site-logo"'\n    # Ensure the CSS link is present before </head>\n    if ($content -notmatch '<link rel="stylesheet" href="/assets/css/logo.css"') {\n        $content = $content -replace '(</head>)', '<link rel="stylesheet" href="/assets/css/logo.css">`n$1'\n    }\n    Set-Content -Path $file -Value $content -Encoding utf8\n    Write-Host "Updated $file"\n}\n